-- Generated by `make contracts` from contracts/ (conformedDimensions) and contracts/models/dim_condition.odcs.yaml. Do not edit: change the contract and regenerate.
-- Concept ids come only from accepted crosswalk records that name their reviewer, date and source;
-- every other label is unresolved. Proposed records are counted for review and change nothing.
with labels as (
    select 'cdc_haicviz_cdi' as dataset_id, condition_key, condition_label,
        string_agg(distinct condition_case_status, '; ' order by condition_case_status) as case_status,
        string_agg(distinct condition_case_subtype, '; ' order by condition_case_subtype) as case_subtype,
        count(*) as row_count
    from {{ ref('int_cdc_haicviz_cdi') }}
    where condition_key is not null
    group by condition_key, condition_label
    union all
    select 'cdc_nhsn_ar_hai' as dataset_id, condition_key, condition_label,
        string_agg(distinct condition_case_status, '; ' order by condition_case_status) as case_status,
        string_agg(distinct condition_case_subtype, '; ' order by condition_case_subtype) as case_subtype,
        count(*) as row_count
    from {{ ref('int_cdc_nhsn_ar_hai') }}
    where condition_key is not null
    group by condition_key, condition_label
    union all
    select 'cdc_nndss_weekly' as dataset_id, condition_key, condition_label,
        string_agg(distinct condition_case_status, '; ' order by condition_case_status) as case_status,
        string_agg(distinct condition_case_subtype, '; ' order by condition_case_subtype) as case_subtype,
        count(*) as row_count
    from {{ ref('int_cdc_nndss_weekly') }}
    where condition_key is not null
    group by condition_key, condition_label
    union all
    select 'cdc_respnet' as dataset_id, condition_key, condition_label,
        string_agg(distinct condition_case_status, '; ' order by condition_case_status) as case_status,
        string_agg(distinct condition_case_subtype, '; ' order by condition_case_subtype) as case_subtype,
        count(*) as row_count
    from {{ ref('int_cdc_respnet') }}
    where condition_key is not null
    group by condition_key, condition_label
),

