crosswalk as (
    select * from {{ ref('stg_control_plane__condition_crosswalk') }}
),

accepted as (
    select * from crosswalk
    where state = 'accepted' and synonym is null and reviewer is not null and reviewed_at is not null
        and source is not null
    qualify row_number() over (partition by dataset, label order by reviewed_at desc, record_id desc) = 1
),

proposed as (
    select dataset, label, count(*) as proposals from crosswalk where state = 'proposed'
    group by dataset, label
)

select
    l.condition_key,
    l.dataset_id,
    l.condition_label,
    l.case_status,
    l.case_subtype,
    li.condition_label is not null as is_listed,
    a.mesh_id,
    a.ncbi_taxon_id,
    a.gbd_cause,
    case when a.record_id is not null then 'accepted' else 'unresolved' end as mapping_state,
    a.source as mapping_source,
    a.reviewer as mapping_reviewed_by,
    a.reviewed_at as mapping_reviewed_at,
    coalesce(p.proposals, 0) as open_proposals,
    l.row_count
from labels as l
left join listed as li on li.dataset_id = l.dataset_id and li.condition_label = l.condition_label
left join accepted as a on a.dataset = l.dataset_id and a.label = l.condition_label
left join proposed as p on p.dataset = l.dataset_id and p.label = l.condition_label
